/**
 * What people write around a word in a list, taken off it.
 *
 * The import audit of 26 Oct 2026 (`reports/checks/imports-health.sql`)
 * found three shapes that went into notebooks as they were typed: a list
 * bullet in front of the word or the meaning ("• 先生 (Sensei)"), a reading
 * written beside a Chinese, Japanese or Korean word ("増えます [fuemasu]",
 * "食堂（しょくどう）shokudō") and a meaning carrying its example after a
 * typed "\n" ("disminuir \nEjemplo: 輸出が減ります"). Each rule here keeps
 * everything the learner wrote; it only moves it to the field it belongs in.
 */
import { scriptOf, type Script } from '@lexpad/core';

/** Scripts whose words are written with a reading beside them. */
const CJK: ReadonlySet<Script> = new Set(['han', 'kana', 'hangul']);
const HAS_CJK =
  /[\u3040-\u30FF\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF\u1100-\u11FF\u3130-\u318F\uAC00-\uD7AF]/u;
const HAS_HAN = /[\u3400-\u4DBF\u4E00-\u9FFF\uF900-\uFAFF]/u;
const HAS_LATIN = /\p{Script=Latin}/u;
/** Kana only, with the marks written among kana: ー, 〜, ・ and a space. */
const KANA_ONLY = /^[\u3040-\u30FF\uFF5E\u301C~\u30FB\s]+$/u;

/**
 * A list bullet in front of an entry: "• ", "・", "- ", "* ". A hyphen, a
 * star or a plus needs a space after it, so "-ing" and "*nix" stay words.
 * Numbers are not taken off a single cell ("1. Mai", "2. Weltkrieg" are
 * words): only a whole numbered column loses them (`numberedColumn`).
 */
const BULLET = /^(?:[•·・◦▪▫●○■□►▶‣⁃∙➢➤✓✔☐☑][\s\u00A0]*|[-–—*+][\s\u00A0]+)/u;

/** A number in front of an entry: "1. ", "1) ", "(1) ". */
const NUMBERED = /^(?:\(\d{1,3}\)|\d{1,3}[.)])[\s\u00A0]+/u;

/** The share of a column's cells that must be numbered for the numbers to be the list's, not the words'. */
const NUMBERED_SHARE = 0.9;

/** The text without the bullets in front of it (two at most: "• – word"). */
export function stripListMarker(text: string): string {
  let value = text.trim();
  for (let pass = 0; pass < 2; pass += 1) {
    const match = BULLET.exec(value);
    if (match === null || match[0].length >= value.length) break;
    value = value.slice(match[0].length).trim();
  }
  return value;
}

/** Whether nearly every filled cell of a column opens with a list number ("1. ", "2) "). */
export function numberedColumn(cells: readonly string[]): boolean {
  const filled = cells.map((cell) => stripListMarker(cell)).filter((cell) => cell !== '');
  return (
    filled.length >= 2 &&
    filled.filter((cell) => NUMBERED.test(cell)).length >= filled.length * NUMBERED_SHARE
  );
}

/** The cell without its list number. */
export function stripNumber(text: string): string {
  const value = stripListMarker(text);
  const match = NUMBERED.exec(value);
  return match === null || match[0].length >= value.length
    ? value
    : stripListMarker(value.slice(match[0].length));
}

/**
 * A literal backslash-n (two characters, as some exports and copied JSON
 * write a line break) made a real line break, and so is an HTML `<br>`.
 */
export function realLineBreaks(text: string): string {
  return text.replace(/\\r\\n|\\n|\\r/g, '\n').replace(/<br\s*\/?>/gi, '\n');
}

/**
 * The words that introduce an example, in the languages people write lists
 * in, followed by a colon (or the full-width one). Only at the start of a
 * line (after a real or typed line break, or a `<br>`) or after a full
 * stop: "an example: a single case" is a meaning, not a label.
 */
const EXAMPLE_LABEL =
  /(?:\n|(?<=[.。．!?！？]))\s*(?:e\.g\.|examples?|ejemplos?|exemples?|beispiele?|beispielsatz|esempi[oi]?|exemplos?|örnek|voorbeelden?|przykłady?|příklad|приклад|примеры?|مثال|نمونه|例文?|例句|用例|예문?|ví dụ|contoh|halimbawa)\s*[:：]\s*/iu;

/**
 * A meaning split from the example written after it ("incrementar
 * \nEjemplo: 輸出が増えます"): the text before the label, and the sentence
 * after it. Undefined when there is no label, or nothing on one side.
 */
export function splitExample(text: string): { meaning: string; example: string } | undefined {
  const match = EXAMPLE_LABEL.exec(text);
  if (match === null) return undefined;
  const meaning = text.slice(0, match.index).trim();
  const example = text.slice(match.index + match[0].length).trim();
  if (meaning === '' || example === '' || !/\p{L}/u.test(example)) return undefined;
  return { meaning, example };
}

/* -------------------------------------------------------------- readings */

const MACRONS: Record<string, string> = {
  ā: 'aa',
  ē: 'ee',
  ī: 'ii',
  ō: 'ou',
  ū: 'uu',
  â: 'aa',
  ê: 'ee',
  î: 'ii',
  ô: 'ou',
  û: 'uu',
};

/** One romaji syllable (Hepburn and the usual typing): "shi", "kyo", "n", a doubled consonant. */
const ROMAJI =
  /^(?:(?:ch|sh|ts|tz|dz|j|f|[kgsztdnhbpmrwyv]y?)?[aiueo]|n|m(?=[bmp])|([kgsztdhbpmcfj])(?=\1|ch))+$/;
/** One pinyin syllable, tones as marks or a digit. */
const PINYIN =
  /^(?:(?:zh|ch|sh|[bpmfdtnlgkhjqxrzcsyw])?(?:iang|iong|uang|ueng|ang|eng|ing|ong|ian|iao|uai|uan|van|ai|ei|ao|ou|an|en|in|un|vn|ia|ie|iu|ua|uo|ui|ve|er|a|o|e|i|u|v)r?[1-5]?)+$/;

/**
 * Whether Latin text is a reading (romaji or pinyin) rather than a
 * translation: "fuemasu", "kopī shimasu", "nǐ hǎo" and "ni3 hao3" are;
 * "apple" and "verb" are not. Pinyin without tones is not taken, since
 * "banana" and "man" read as pinyin too.
 */
export function isReading(text: string): boolean {
  return readsAs(text);
}

function readsAs(text: string): boolean {
  const tokens = text
    .trim()
    .toLowerCase()
    .replace(/[~〜'’.]/g, '')
    .split(/[\s-]+/)
    .filter((token) => token !== '');
  if (tokens.length === 0) return false;
  const toned = /[\u0300-\u036F]/u.test(text.normalize('NFD')) || /\d/.test(text);
  return tokens.every((token) => {
    if (!/^[\p{Script=Latin}\p{M}0-9]+$/u.test(token)) return false;
    const bare = (value: string): string => value.normalize('NFD').replace(/[\u0300-\u036F]/gu, '');
    const romaji = bare([...token].map((char) => MACRONS[char] ?? char).join('')).replace(/\d/g, '');
    if (ROMAJI.test(romaji)) return true;
    return toned && PINYIN.test(bare(token.replace(/ü/g, 'v')));
  });
}

/** The reading written beside a word, as it will show: the kana, then the romaji. */
function readingOf(kana: string, latin: string): string {
  const a = kana.trim();
  const b = latin.trim();
  if (a !== '' && b !== '') return `${a} (${b})`;
  return a || b;
}

/** Whether text is a word in a script written with readings, with no Latin in it. */
function isCjkWord(text: string): boolean {
  return text !== '' && HAS_CJK.test(text) && !HAS_LATIN.test(text) && !/[()（）[\]［］]/.test(text);
}

const BRACKETED = /^(.+?)\s*[[［]\s*([^[\]［］]+?)\s*[\]］]$/u;
const PARENTHESISED = /^(.+?)\s*[（(]\s*([^()（）]+?)\s*[）)]\s*([^()（）]*)$/u;
const TRAILING = /^([^\p{Script=Latin}]+?)\s+([\p{Script=Latin}\p{M}0-9'’~ \-.]+)$/u;

/**
 * A Chinese, Japanese or Korean headword without the reading written
 * beside it, and that reading: "増えます [fuemasu]", "食堂（しょくどう）
 * shokudō", "先生 (Sensei)", "ボタン botan". A Japanese list written kana
 * first ("こたえます (答えます)") gives the kanji as the word and the kana
 * as its reading. Anything else (a gloss in brackets, a note such as "[な]")
 * is left as it was written.
 */
export function splitReading(
  headword: string,
  options: { glosses?: boolean } = {},
): { headword: string; reading: string } | undefined {
  const text = headword.trim();
  if (!CJK.has(scriptOf(text))) return undefined;
  // Korean is romanised by other rules than romaji, and "아니요 (no)" is a gloss.
  if (/[\u1100-\u11FF\u3130-\u318F\uAC00-\uD7AF]/u.test(text)) return undefined;
  // A row with no meaning may carry its translation in brackets: "名 (name)".
  // Then only kana counts as a reading.
  const reads = (value: string): boolean => options.glosses !== true && readsAs(value);

  const bracketed = BRACKETED.exec(text);
  if (bracketed !== null) {
    const [, word = '', inside = ''] = bracketed;
    if (isCjkWord(word) && reads(inside)) return { headword: word, reading: inside.trim() };
  }

  const parenthesised = PARENTHESISED.exec(text);
  if (parenthesised !== null) {
    const [, word = '', inside = '', after = ''] = parenthesised;
    const latinAfter = after.trim() === '' || reads(after);
    if (isCjkWord(word) && latinAfter) {
      // 語（かな）romaji, or 語 (kana)
      if (KANA_ONLY.test(inside) && HAS_HAN.test(word))
        return { headword: word, reading: readingOf(inside, after) };
      // かな (漢字): the kanji is the word as it is written
      if (
        KANA_ONLY.test(word) &&
        HAS_HAN.test(inside) &&
        isCjkWord(inside) &&
        !/[、,，／/;；]/.test(inside) &&
        after.trim() === ''
      )
        return { headword: inside.trim(), reading: word };
      // 語 (romaji)
      if (after.trim() === '' && reads(inside)) return { headword: word, reading: inside.trim() };
    }
  }

  const trailing = TRAILING.exec(text);
  if (trailing !== null) {
    const [, word = '', latin = ''] = trailing;
    if (isCjkWord(word.trim()) && reads(latin)) return { headword: word.trim(), reading: latin.trim() };
  }
  return undefined;
}

/**
 * The word a headword stands for, for telling two entries apart: without a
 * bullet and without a written reading, so "食堂 [shokudou]" and
 * "食堂（しょくどう）shokudō" are one word.
 */
export function bareHeadword(headword: string): string {
  const stripped = stripListMarker(headword);
  return splitReading(stripped)?.headword ?? stripped;
}

/**
 * The script a text is mainly written in: its bullets, and anything in
 * brackets after the word ("先生 (Sensei)", "Profesor (先生)"), set aside
 * first, so a gloss or a reading does not decide it.
 */
export function mainScript(text: string): Script {
  const stripped = stripListMarker(text);
  const outside = stripped.replace(/[([（［][^()（）[\]［］]*[)\]）］]/gu, ' ').trim();
  return scriptOf(/\p{L}/u.test(outside) ? outside : stripped);
}
