import { useEffect, useRef, useState } from 'react';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import styles from './LengthHint.module.css';

/**
 * From this share of a field's limit, the count shows: early enough to see
 * the end coming, late enough that ordinary typing never sees it.
 */
export const LENGTH_HINT_FROM = 0.9;

/**
 * "1,912 / 2,000" under a field that is close to its limit (owner, 26 Oct
 * 2026: a learner should never type text the server later cuts). The field
 * itself stops at the limit with `maxLength`; this says where that is.
 * Nothing shows below `LENGTH_HINT_FROM` of the limit.
 *
 * It counts `value.length`, the UTF-16 units `maxLength` counts, so it turns
 * red exactly when the field stops taking more. Placed straight after its
 * field, it also hears the field's pastes: one that `maxLength` cut short
 * says so ("Only the first 2,000 characters fit.") until the text is
 * shorter again.
 */
export function LengthHint({ value, max }: { value: string; max: number }): React.JSX.Element {
  const anchor = useRef<HTMLSpanElement>(null);
  /** The text's length when a paste was cut short, or undefined. */
  const [cutFrom, setCutFrom] = useState<number | undefined>();

  useEffect(() => {
    const field = anchor.current?.previousElementSibling;
    if (!(field instanceof HTMLInputElement || field instanceof HTMLTextAreaElement)) return;
    const onPaste = (event: Event): void => {
      const pasted = (event as ClipboardEvent).clipboardData?.getData('text') ?? '';
      const selected = (field.selectionEnd ?? 0) - (field.selectionStart ?? 0);
      if (field.value.length - selected + pasted.length > max) setCutFrom(field.value.length - selected);
    };
    field.addEventListener('paste', onPaste);
    return () => {
      field.removeEventListener('paste', onPaste);
    };
  }, [max]);

  // The line about a cut paste goes once the text is shorter than it was
  // before that paste (state adjusted while rendering, React's pattern).
  const count = value.length;
  if (cutFrom !== undefined && count < cutFrom) setCutFrom(undefined);
  const cut = cutFrom !== undefined && count >= max;

  const near = count >= max * LENGTH_HINT_FROM;
  return (
    <span ref={anchor} className={styles.anchor}>
      {near && (
        <span className={cx(styles.hint, count >= max && styles.full)} aria-live="polite">
          {cut && <span className={styles.cut}>{t('field.pasteCut', { max: max.toLocaleString() })} </span>}
          <bdi dir="ltr">
            {t('field.length', { count: count.toLocaleString(), max: max.toLocaleString() })}
          </bdi>
        </span>
      )}
    </span>
  );
}
