import type { LanguageCode } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { t } from '@/i18n/index.js';
import styles from './SpellingPrompt.module.css';

interface SpellingPromptProps {
  suggestion: string;
  lang: LanguageCode;
  onUse: () => void;
  onKeep: () => void;
}

/**
 * "Did you mean …?" in the add sheet, the moment the card arrives. The card
 * the model wrote is already for the suggested word, so Use only renames;
 * nothing is asked of the model again. Keep mine leaves the suggestion on
 * the word, and its page asks once more, where it can be answered for good.
 */
export function SpellingPrompt({ suggestion, lang, onUse, onKeep }: SpellingPromptProps): React.JSX.Element {
  return (
    <div className={styles.prompt} role="status">
      <p className={styles.text}>
        {t('add.didYouMean')}{' '}
        <Bilingual lang={lang} className={styles.word}>
          {suggestion}
        </Bilingual>
        {t('add.didYouMeanEnd')}
      </p>
      <div className={styles.actions}>
        <button type="button" className={styles.use} onClick={onUse}>
          {t('add.useSuggestion', { word: suggestion })}
        </button>
        <button type="button" className={styles.keep} onClick={onKeep}>
          {t('word.keepMine')}
        </button>
      </div>
    </div>
  );
}
