/**
 * Which two languages a set of words is in, worked out on this device.
 *
 * Owner, 26 Oct 2026: "make sure the language is detected automatically".
 * The honest version, as in `route.ts`: the writing system is knowable, so
 * that decides first; among the languages that share a script, a letter
 * only one of them writes, and for Latin a small list of common words and
 * endings, narrow it further. When that still leaves a doubt the answer is
 * "don't know", never a guess. Nothing here asks a server or a model, and
 * nothing here changes a notebook: a suggestion is only ever applied by the
 * learner's tap.
 */
import { couldBe, languagesInScript, scriptOfLanguage, type LanguageCode, type Script } from '@lexpad/core';
import { mainScript } from '@/features/settings/transfer/tidy.js';

/** A notebook's two languages. */
export interface Pair {
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
}

/** One entry as the guess reads it: the word, and its first meaning if it has one. */
export interface Sample {
  headword: string;
  meaning?: string | undefined;
}

/**
 * How many of a notebook's first words the guess reads: enough to be sure,
 * few enough to read on every visit.
 */
export const PAIR_SAMPLE_WORDS = 20;

/**
 * The share of the entries that must agree on a script before a different
 * pair is suggested. A suggestion changes the notebook's languages, so it
 * waits for words that clearly say so.
 */
export const PAIR_CLEAR_SHARE = 0.8;

/** At least this many entries with a readable script before anything is said. */
export const PAIR_MIN_SAMPLES = 3;

/** The script most of these texts are in, when at least `share` of them agree. */
export function majorityScript(texts: readonly string[], share: number): Script | undefined {
  const counts = new Map<Script, number>();
  let read = 0;
  for (const text of texts) {
    const script = mainScript(text);
    if (script === 'unknown') continue;
    read += 1;
    counts.set(script, (counts.get(script) ?? 0) + 1);
  }
  if (read === 0) return undefined;
  // Japanese words are written in kana and in Han: one list, one script.
  if (counts.has('kana') && counts.has('han')) {
    counts.set('kana', (counts.get('kana') ?? 0) + (counts.get('han') ?? 0));
    counts.delete('han');
  }
  const [top, count] = [...counts.entries()].sort((a, b) => b[1] - a[1])[0] ?? [];
  if (top === undefined || count === undefined || count < read * share) return undefined;
  return top;
}

/** Whether text in this script can be a word of this language. */
export function scriptFits(script: Script, language: LanguageCode): boolean {
  const expected = scriptOfLanguage(language);
  if (script === expected) return true;
  // Japanese is written in kana and Han; Korean sometimes in Han.
  return script === 'han' && (expected === 'kana' || expected === 'hangul');
}

/**
 * Which language of a script, best first, when the script alone does not
 * settle it: the language most learners of that script mean, kept only
 * while the text's own letters allow it (`couldBe`).
 */
const PREFERRED: Partial<Record<Script, readonly LanguageCode[]>> = {
  arabic: ['fa', 'ar', 'ur'],
  cyrillic: ['ru', 'uk'],
  devanagari: ['hi'],
};

/* -------------------------------------------------------------- Latin */

type LatinCandidate = 'en' | 'es' | 'fr' | 'de' | 'it' | 'pt' | 'nl' | 'tr' | 'pl';

