/** Letters only one or two of them write. */
const LETTERS: Record<LatinCandidate, RegExp> = {
  en: /^$/,
  es: /[ñ¿¡]/,
  fr: /[èêëîïûùœ]/,
  de: /[äß]/,
  it: /[ìò]/,
  pt: /[ãõ]/,
  nl: /ij/,
  tr: /[ışğ]/,
  pl: /[ąęłńśźż]/,
};

/** Endings a word of the language often has. */
const ENDINGS: Record<LatinCandidate, RegExp> = {
  en: /(?:tion|ing|ly|ness|ful|less|ship|ed|ity|ous|ive|able|ible|th|ght|wh|ck)$|^(?:th|wh|w)/,
  es: /(?:ción|dad|mente|oso|osa|ar|er|ir|ito|ita|ado|ada)$/,
  fr: /(?:eux|euse|eau|aux|oir|ière|ette|ité|é|ée)$/,
  de: /(?:ung|keit|heit|lich|chen|isch|schaft)$|sch/,
  it: /(?:zione|mente|are|ere|ire|ità|etto|etta|ino|ina)$/,
  pt: /(?:ção|ções|ões|mente|dade|inho|inha)$/,
  nl: /(?:heid|lijk|tje|en)$|oe|aa/,
  tr: /(?:lar|ler|mak|mek|lık|lik|cı|ci)$/,
  pl: /(?:ość|ski|cja|nie|ać|eć)$|sz|cz|rz/,
};

const CANDIDATES = Object.keys(COMMON) as LatinCandidate[];
const COMMON_SETS = new Map<LatinCandidate, ReadonlySet<string>>(
  CANDIDATES.map((code) => [code, new Set(COMMON[code])]),
);

/** A clear winner needs this many points… */
const LATIN_MIN_SCORE = 4;
/** …and this many times the runner-up's. */
const LATIN_LEAD = 1.5;

/**
 * Which Latin-script language these texts are in, or undefined when the
 * words do not clearly say. Points for a common word, a letter of the
 * language's own and a typical ending.
 */
export function guessLatinLanguage(texts: readonly string[]): LanguageCode | undefined {
  const score = new Map<LatinCandidate, number>(CANDIDATES.map((code) => [code, 0]));
  const add = (code: LatinCandidate, points: number): void => {
    score.set(code, (score.get(code) ?? 0) + points);
  };
  for (const text of texts) {
    const tokens = text
      .toLowerCase()
      .split(/[^\p{L}]+/u)
      .filter((token) => token !== '');
    for (const token of tokens) {
      for (const code of CANDIDATES) {
        if (COMMON_SETS.get(code)?.has(token) === true) add(code, 2);
        if (code !== 'en' && LETTERS[code].test(token)) add(code, 3);
        if (token.length > 3 && ENDINGS[code].test(token)) add(code, 1);
      }
    }
  }
  const ranked = [...score.entries()].sort((a, b) => b[1] - a[1]);
  const [first, second] = ranked;
  if (first === undefined || first[1] < LATIN_MIN_SCORE) return undefined;
  if (second !== undefined && first[1] < second[1] * LATIN_LEAD) return undefined;
  return first[0];
}

/**
 * The language a side of a list is in, given its script: the notebook's
 * own language when it fits, then the other side's, then the one language
 * that script can mean.
 */
function languageOf(
  script: Script,
  texts: readonly string[],
  own: LanguageCode,
  other: LanguageCode,
): LanguageCode | undefined {
  if (scriptFits(script, own)) return own;
  if (scriptFits(script, other)) return other;
  if (script === 'latin') return guessLatinLanguage(texts);
  // Han with kana anywhere beside it is Japanese.
  if (script === 'han') return texts.some((text) => /[぀-ヿ]/u.test(text)) ? 'ja' : 'zh';
  const all = languagesInScript(script);
  if (all.length === 1) return all[0];
  const fitting = couldBe(texts.join(' '), all);
  if (fitting.length === 1) return fitting[0];
  return PREFERRED[script]?.find((code) => fitting.includes(code));
}

/**
 * The pair these entries are written in, when it is clearly not the
 * notebook's own; undefined when it is, when they do not say, or when the
 * entries are only the notebook's two languages the wrong way round (that
 * is a swap of columns, not of languages).
 */
export function suggestPair(
  samples: readonly Sample[],
  current: Pair,
  share: number = PAIR_CLEAR_SHARE,
): Pair | undefined {
  const headwords = samples.map((sample) => sample.headword);
  const meanings = samples.map((sample) => sample.meaning ?? '').filter((text) => text.trim() !== '');
  const read = headwords.filter((text) => mainScript(text) !== 'unknown').length;
  if (read < Math.min(PAIR_MIN_SAMPLES, samples.length) || read === 0) return undefined;

  const wordScript = majorityScript(headwords, share);
  if (wordScript === undefined) return undefined;
  const meaningScript = meanings.length === 0 ? undefined : majorityScript(meanings, share);
  if (meanings.length > 0 && meaningScript === undefined) return undefined;

  const targetLang = languageOf(wordScript, headwords, current.targetLang, current.meaningLang);
  const meaningLang =
    meaningScript === undefined
      ? current.meaningLang
      : languageOf(meaningScript, meanings, current.meaningLang, current.targetLang);
  if (targetLang === undefined || meaningLang === undefined) return undefined;
  if (targetLang === current.targetLang && meaningLang === current.meaningLang) return undefined;
  if (targetLang === current.meaningLang && meaningLang === current.targetLang) return undefined;
  // Learning a language with meanings in the same one is a choice some
  // learners make; only a pair that differs from the notebook's is worth
  // a word, and "English → English" from a Chinese notebook is not one.
  if (targetLang === meaningLang && current.targetLang !== current.meaningLang) return undefined;
  return { targetLang, meaningLang };
}
