import { cx } from '@/lib/cx.js';
import styles from './Chip.module.css';

/** A horizontally scrolling row of chips, as the notebook filters use. */
export function ChipRow({
  children,
  label,
}: {
  children: React.ReactNode;
  label: string;
}): React.JSX.Element {
  return (
    <div className={styles.row} role="group" aria-label={label}>
      {children}
    </div>
  );
}

interface ChipProps {
  selected?: boolean;
  count?: number | undefined;
  onClick: () => void;
  children: React.ReactNode;
}

/** One selectable chip. */
export function Chip({ selected = false, count, onClick, children }: ChipProps): React.JSX.Element {
  return (
    <button
      type="button"
      className={cx(styles.chip, selected && styles.selected)}
      aria-pressed={selected}
      onClick={onClick}
    >
      {children}
      {count !== undefined && <span className={styles.count}>{count}</span>}
    </button>
  );
}
